def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
 return h.hexdigest()
def main():
 parser=argparse.ArgumentParser();parser.add_argument('--destino',type=Path,default=Path('HRF_POL_BRUTOS_ZIPS'));a=parser.parse_args();a.destino.mkdir(parents=True,exist_ok=True)
 for part in PARTS:
  p=a.destino/part['name']
  if p.exists():
   if p.stat().st_size==part['bytes'] and sha(p)==part['sha256']:
    print('Já verificado:',p.name,flush=True);continue
   raise ValueError('Arquivo existente diverge do manifesto: '+str(p))
  tmp=p.with_suffix('.zip.download');offset=tmp.stat().st_size if tmp.exists() else 0
  if offset>part['bytes']:raise ValueError('Parcial maior que o esperado: '+str(tmp))
  if offset<part['bytes']:
   request=urllib.request.Request(part['url'],headers={'Range':f'bytes={offset}-'} if offset else {})
   print('Baixando',p.name,flush=True)
   with urllib.request.urlopen(request,timeout=120) as source:
    if source.status==206:
     if not offset or not source.headers.get('Content-Range','').startswith(f'bytes {offset}-'):raise ValueError('Resposta parcial incompatível')
     mode='ab'
    elif source.status==200:mode='wb'
    else:raise ValueError('HTTP '+str(source.status))
    with tmp.open(mode) as target:
     for b in iter(lambda:source.read(1024*1024),b''):target.write(b)
  assert tmp.stat().st_size==part['bytes'] and sha(tmp)==part['sha256'],p.name
  with zipfile.ZipFile(tmp) as z:assert z.testzip() is None
  os.replace(tmp,p);print('Verificado:',p.name,flush=True)
 print('Todos os 37 ZIPs verificados em',a.destino.resolve())
if __name__=='__main__':main()
